import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.Bb5YUzRP.js";import{Ar as i,Br as a,Cr as o,Dr as s,Er as c,Fr as l,Gr as u,Hr as d,Ir as f,Jr as p,Kr as m,Lr as h,Mr as g,Nr as _,Or as v,Pr as y,Qr as b,Rr as x,Sr as S,Tr as C,Ur as w,Vr as T,Wr as ee,Xr as E,Yr as D,Zr as O,jr as k,kr as A,qr as j,wr as M,xr as N,zr as P}from"./chunks/assets.DMxVpLII.js";var F=JSON.parse(`{"title":"Image options","description":"","frontmatter":{},"headers":[],"relativePath":"product-config/image-options.md","filePath":"product-config/image-options.md"}`),I={name:`product-config/image-options.md`},L=b+` 1x, `+O+` 2x`,R=E+` 1x, `+D+` 2x`,z=p+` 1x, `+j+` 2x`,B=m+` 1x, `+u+` 2x`,V=ee+` 1x, `+w+` 2x`,H=d+` 1x, `+T+` 2x`,U=a+` 1x, `+P+` 2x`,W=x+` 1x, `+h+` 2x`,G=f+` 1x, `+l+` 2x`,K=y+` 1x, `+_+` 2x`,q=g+` 1x, `+k+` 2x`,J=i+` 1x, `+A+` 2x`,Y=v+` 1x, `+s+` 2x`,X=c+` 1x, `+C+` 2x`,Z=M+` 1x, `+o+` 2x`,Q=S+` 1x, `+N+` 2x`;function $(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="image-options" tabindex="-1">Image options <a class="header-anchor" href="#image-options" aria-label="Permalink to “Image options”">​</a></h1><p>In this tab, you can configure options related to the design images</p><p><img src="/webp/image-options.jpg-90-1794236257025.webp" srcset="`+L+`" alt="Image options" title="" width="770" height="650" loading="lazy" style="width:385px;"></p><h2 id="allow-image-upload" tabindex="-1">Allow image upload <a class="header-anchor" href="#allow-image-upload" aria-label="Permalink to “Allow image upload”">​</a></h2><p>Enabled customer uploads. You can control <a href="/configuration/design-options.html#upload-max-size">the maximum upload size</a> in the main configuration page</p><p><img src="/webp/image-upload.jpg-90-1794236257032.webp" srcset="`+R+`" alt="Image upload" title="" width="624" height="268" loading="lazy" style="width:312px;"></p><h2 id="enable-image-background-remover" tabindex="-1">Enable image background remover <a class="header-anchor" href="#enable-image-background-remover" aria-label="Permalink to “Enable image background remover”">​</a></h2><p>The background remover icon will be displayed in the image tab as well as in the design image icons.</p><p>Starting with an image that has a background, for example:</p><p><img src="/webp/squirrel.jpg-90-1794236257116.webp" srcset="`+z+`" alt="Squirrel" title="" width="310" height="421" loading="lazy" style="width:155px;"></p><p>We can remove the background like this</p><p><img src="/webp/bg-remover-btn.jpg-90-1794236256932.webp" srcset="`+B+`" alt="Bg remover btn" title="" width="656" height="890" loading="lazy" style="width:328px;"></p><p>We can adjust the sensitivity to better match the background color variations</p><p><img src="/webp/bg-remover.jpg-90-1794236256936.webp" srcset="`+V+`" alt="Bg remover" title="" width="732" height="1140" loading="lazy" style="width:366px;"></p><p>Then we apply to get the result</p><p><img src="/webp/bg-remover-result.jpg-90-1794236256934.webp" srcset="`+H+`" alt="Bg remover result" title="" width="946" height="1288" loading="lazy" style="width:473px;"></p><h2 id="enable-pixabay-search" tabindex="-1">Enable Pixabay search <a class="header-anchor" href="#enable-pixabay-search" aria-label="Permalink to “Enable Pixabay search”">​</a></h2><p>Pixabay is a free image search service. Before you enable this service, make sure to configure your <a href="/configuration/image-options.html#pixabay-key">Pixabay key</a>.</p><p>When enabled, the module will display a search field in the Image tab.</p><p><img src="/webp/pixabay-search.jpg-90-1794236257074.webp" srcset="`+U+`" alt="Pixabay search" title="" width="638" height="480" loading="lazy" style="width:319px;"></p><p>The customer can enter a search term then submit. The search results will be displayed like this.</p><p><img src="/webp/pixabay-results.jpg-90-1794236257073.webp" srcset="`+W+`" alt="Pixabay results" title="" width="2240" height="1290" loading="lazy" style="width:1120px;"></p><p>When the customer clicks and image, it will be magnified and displayed inside an image gallery like this</p><p><img src="/webp/pixabay-gallery.jpg-90-1794236257069.webp" srcset="`+G+`" alt="Pixabay gallery" title="" width="1888" height="1751" loading="lazy" style="width:944px;"></p><p>The customer can add the image to the design by clicking the insert button</p><h2 id="enable-instagram-image-import" tabindex="-1">Enable Instagram image import <a class="header-anchor" href="#enable-instagram-image-import" aria-label="Permalink to “Enable Instagram image import”">​</a></h2><p>Make sure to configure your Instagram App details in the <a href="/configuration/image-options.html#instagram-app-id">main configuration section</a></p><p>When enabled, this button will be displayed</p><p><img src="/webp/instagram-btn.jpg-90-1794236257037.webp" srcset="`+K+`" alt="Instagram btn" title="" width="620" height="452" loading="lazy" style="width:310px;"></p><p>When the customer clicks the button, a popup will open to allow the customer to confirm the app access to their images</p><p><img src="/webp/instagram-popup.png-90-1794236257039.webp" srcset="`+q+`" alt="Instagram popup" title="" width="938" height="1352" loading="lazy" style="width:469px;"></p><p>The images will be displayed like this</p><p><img src="/webp/instagram-images.jpg-90-1794236257037.webp" srcset="`+J+`" alt="Instagram images" title="" width="1794" height="590" loading="lazy" style="width:897px;"></p><h2 id="enable-image-transparency" tabindex="-1">Enable image transparency <a class="header-anchor" href="#enable-image-transparency" aria-label="Permalink to “Enable image transparency”">​</a></h2><p>This will display a slider that changes the image transparency</p><p><img src="/webp/image-transparency.jpg-90-1794236257030.webp" srcset="`+Y+`" alt="Image transparency" title="" width="1328" height="590" loading="lazy" style="width:664px;"></p><h2 id="enable-image-brightness" tabindex="-1">Enable image brightness <a class="header-anchor" href="#enable-image-brightness" aria-label="Permalink to “Enable image brightness”">​</a></h2><p>If enabled, a brightness slider will be displayed</p><p><img src="/webp/image-brightness.jpg-90-1794236256989.webp" srcset="`+X+`" alt="Image brightness" title="" width="1160" height="722" loading="lazy" style="width:580px;"></p><h2 id="enable-image-contrast" tabindex="-1">Enable image contrast <a class="header-anchor" href="#enable-image-contrast" aria-label="Permalink to “Enable image contrast”">​</a></h2><p>A contrast slider will be displayed if this option is active</p><p><img src="/webp/image-contrast.jpg-90-1794236256997.webp" srcset="`+Z+`" alt="Image contrast" title="" width="1258" height="688" loading="lazy" style="width:629px;"></p><h2 id="enable-image-flip" tabindex="-1">Enable image flip <a class="header-anchor" href="#enable-image-flip" aria-label="Permalink to “Enable image flip”">​</a></h2><p>This will display horizontal and vertical flip buttons in the image tab</p><p><img src="/webp/image-flip-btns.jpg-90-1794236257020.webp" srcset="`+Q+`" alt="Image flip btns" title="" width="174" height="116" loading="lazy" style="width:87px;"></p>`,45)]])}var te=e(I,[[`render`,$]]);export{F as __pageData,te as default};